/* Venture, Capital & How Money Moves.

   Built for someone who intends to run a venture fund or a family office, and
   who therefore needs two different things: the vocabulary to never be lost in
   a room, and the mechanics to know what is actually happening when the
   vocabulary is used.

   The order is designed. The language comes first because every later phase
   assumes it. Fund mechanics come before company financing because a GP's
   decisions about a company are downstream of how their fund is built. The
   firms come late, because "who did what" is only interesting once you know
   what the what is.

   A deliberate omission: no card asks who is currently a partner where.
   People move constantly, and a deck that teaches a 2026 roster is a deck
   that teaches something false by 2027. People appear here where the fact is
   durable — who founded a firm, who led a defining deal, who wrote the book. */

export const PHASES = [
  { id: 'language',  name: 'The Language',              why: 'Every later phase assumes these words. Fumbling one in a room costs you credibility you will not get back in that meeting.' },
  { id: 'fund',      name: 'How a Fund Is Built',       why: 'A GP’s every decision is downstream of the document that governs their fund.' },
  { id: 'portfolio', name: 'Portfolio Construction',    why: 'The power law is not a slogan. It dictates ownership targets, reserves and how many shots you take.' },
  { id: 'lps',       name: 'The Money Behind the Money',why: 'You cannot raise from someone whose job you do not understand.' },
  { id: 'financing', name: 'Financing a Company',       why: 'The ladder from a first cheque to an exit, and the instruments at each rung.' },
  { id: 'terms',     name: 'Term Sheets, Clause by Clause', why: 'Most of the money is decided by clauses nobody reads aloud.' },
  { id: 'captable',  name: 'Cap Tables & Dilution',     why: 'Ownership is arithmetic. Doing it in your head is a competitive advantage.' },
  { id: 'judging',   name: 'Judging a Company',         why: 'The numbers that tell you whether a business is working, and the ones that lie.' },
  { id: 'firms',     name: 'The Firms & The People',    why: 'The industry runs on shared history. Knowing it is how you follow a conversation.' },
  { id: 'mountain',  name: 'The Mountain West',         why: 'Your own backyard, and the network you can actually reach.' },
  { id: 'plumbing',  name: 'The Plumbing',              why: 'How money physically moves, and who touches it on the way.' },
  { id: 'rules',     name: 'Rules, Tax & History',      why: 'The constraints that shape every structure, and the crashes that wrote them.' },
];

const P = PHASES.reduce((m, p) => ({ ...m, [p.id]: p.name }), {});
const card = (phase, front, back, group) => ({ front, back, category: P[phase], group: group || null });

